--[=[
    @class EventBus
    @server
    @client

    EventBus 提供了统一的事件总线，整合了以下业务：

    * 客户端-客户端
    * 服务端-服务端
    * 客户端-服务端
    * 服务单-客户端

    事件的发送方和接收方不再需要创建/查找事件实体。

    ```lua
    -- 引用事件总线
    require(game.ReplicatedStorage.EventBus)
    ```
	
]=]
local Channel = require(script.Channel)
local logger = require(game.ReplicatedStorage.Packages.LoggerManager).GetLogger("EventBus")
local EventProvider = require(script.EventProvider)

local EventBus = {}
local _channels = {}

function EventBus.GetChannel(channelName: string): Channel.Type
	channelName = channelName or "default"
	if not _channels[channelName] then
		local clone = script.Channel:Clone()
		local module = require(clone)
		_channels[channelName] = module.new(channelName, EventProvider, logger)
	end
	return _channels[channelName]
end

--[=[
	抛出事件,客户端对客户端，或者服务端对服务端
]=]
function EventBus.Fire(eventName: string, ...: any)
	local channel = EventBus.GetChannel()
	channel.Fire(eventName, ...)
end

--[=[
	客户端发送事件给服务端
	@client
]=]
function EventBus.FireServer(eventName: string, ...: any)
	local channel = EventBus.GetChannel()
	channel.FireServer(eventName, ...)
end

--[=[
	服务端发送事件给客户端
	@server
]=]
function EventBus.FireClient(player: Player, eventName: string, ...: any)
	local channel = EventBus.GetChannel()
	channel.FireClient(player, eventName, ...)
end

--[=[
	服务端发送事件给所有客户端
	@server
]=]
function EventBus.FireAllClients(eventName: string, ...: any)
	local channel = EventBus.GetChannel()
	channel.FireAllClients(eventName, ...)
end

--[=[
    注册事件,可以接受如下事件
    * 客户端内部
    * 服务端内部
]=]
function EventBus.Connect(func: (eventName: string, ...any) -> ()): RBXScriptConnection
	local channel = EventBus.GetChannel()
	return channel.Connect(func)
end

--[=[
	注册客户端发送给服务端事件
	@server
]=]
function EventBus.ConnectC2S(func: (player: Player, eventName: string, ...any) -> ()): RBXScriptConnection
	local channel = EventBus.GetChannel()
	return channel.ConnectC2S(func)
end

--[=[
	注册服务端发送给客户端事件
	@client
]=]
function EventBus.ConnectS2C(func: (eventName: string, ...any) -> ()): RBXScriptConnection
	local channel = EventBus.GetChannel()
	return channel.ConnectS2C(func)
end

function EventBus.Invoke(eventName: string, ...: any): any
	local channel = EventBus.GetChannel()
	return channel.Invoke(eventName, ...)
end

function EventBus.InvokeServer(eventName: string, ...: any): any
	local channel = EventBus.GetChannel()
	return channel.InvokeServer(eventName, ...)
end

function EventBus.OnInvoke(func: (eventName: string, ...any) -> ()): RBXScriptConnection
	local channel = EventBus.GetChannel()
	return channel.OnInvoke(func)
end

function EventBus.OnInvokeC2S(func: (player: Player, eventName: string, ...any) -> ()): RBXScriptConnection
	local channel = EventBus.GetChannel()
	return channel.OnInvokeC2S(func)
end

EventBus.RemoteEvent = script.EventProvider:WaitForChild("default_RemoteEvent")
EventBus.BindableEvent = script.EventProvider:WaitForChild("default_BindableEvent")

table.freeze(EventBus)

return EventBus :: Channel.Type & {GetChannel: (channelName: string) -> Channel.Type}
